templates.template:
Component: \{component.name} v\{component.version}
  Assets:\{component.assets.map(a -> '
    - ' + a.name + ' (' + a.size + ' bytes)')}

Asset: \{asset.name}
Path: \{asset.path}
Size: \{asset.size} bytes
Content Type: \{asset.contentType}
Last Modified: \{asset.lastModified}
Downloads: \{asset.downloadCount}

# Repository Summary: \{repo.name}

Type: \{repo.type}
Format: \{repo.format}
Status: \{repo.online ? 'Online' : 'Offline'}

## Statistics

- Components: \{repo.stats.componentCount}
- Assets: \{repo.stats.assetCount}
- Size: \{repo.stats.sizeInBytes < 1024 ? repo.stats.sizeInBytes + ' B' : repo.stats.sizeInBytes < 1048576 ? String.format('%.2f KB', repo.stats.sizeInBytes / 1024.0) : repo.stats.sizeInBytes < 1073741824 ? String.format('%.2f MB', repo.stats.sizeInBytes / 1048576.0) : String.format('%.2f GB', repo.stats.sizeInBytes / 1073741824.0)}

## Recent Activity
\{repo.recentActivity.map(a -> '- ' + a.action + ' ' + a.component + ' at ' + a.timestamp).join('
')}

# Security Audit Report

Generated: \{report.generatedAt}
Period: \{report.startDate} to \{report.endDate}

## Summary

- Total Events: \{report.totalEvents}
- Authentication Failures: \{report.authFailures}
- Permission Denied: \{report.permissionDenied}
- Suspicious Activities: \{report.suspiciousActivities}

## Top Users
\{report.topUsers.map((user, count) -> '- ' + user + ': ' + count + ' events').join('
')}

## Critical Events
\{report.criticalEvents.map(e -> '- ' + e.timestamp + ' | ' + e.user + ' | ' + e.action + ' | ' + e.outcome).join('
')}

# System Health Report

Generated: \{report.timestamp}

## System Resources

- CPU Usage: \{String.format('%.1f%%', report.cpuUsage * 100)}
- Memory Usage: \{String.format('%.1f%%', report.memoryUsage * 100)} (\{report.usedMemory} / \{report.totalMemory})
- Disk Usage: \{String.format('%.1f%%', report.diskUsage * 100)} (\{report.usedDiskSpace} / \{report.totalDiskSpace})

## Repository Health
\{report.repositories.map(r -> '- ' + r.name + ': ' + (r.healthy ? 'Healthy' : 'Issues Detected') + (r.healthy ? '' : ' (' + r.issues.join(', ') + ')')).join('
')}

## Recent Errors
\{report.recentErrors.isEmpty() ? 'No errors reported.' : report.recentErrors.map(e -> '- ' + e.timestamp + ' | ' + e.level + ' | ' + e.message).join('
')}
